// src/sw.js
// Workbox service worker generated by VitePWA. This file is referenced in vite.config.js
// It implements caching strategies for static assets and API GET requests.

import { precacheAndRoute } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { CacheFirst, NetworkFirst, StaleWhileRevalidate } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';

// Pre‑cache all assets generated by Vite (self.__WB_MANIFEST is injected at build time)
precacheAndRoute(self.__WB_MANIFEST || []);

// ------------------------------------------------------------------
// Cache‑first for static assets (fonts, images, JS/CSS bundles)
// ------------------------------------------------------------------
registerRoute(
  ({ request }) => request.destination === 'script' || request.destination === 'style' || request.destination === 'image' || request.destination === 'font',
  new CacheFirst({
    cacheName: 'static-assets',
    plugins: [
      new ExpirationPlugin({
        maxEntries: 100,
        maxAgeSeconds: 30 * 24 * 60 * 60, // 30 days
      }),
    ],
  })
);

// ------------------------------------------------------------------
// Network‑first for API GET requests – fallback to cache when offline
// ------------------------------------------------------------------
registerRoute(
  ({ url, request }) => request.method === 'GET' && url.pathname.startsWith('/api/'),
  new NetworkFirst({
    cacheName: 'api-cache',
    networkTimeoutSeconds: 5,
    plugins: [
      new ExpirationPlugin({
        maxEntries: 200,
        maxAgeSeconds: 7 * 24 * 60 * 60, // 7 days
      }),
    ],
  })
);

// ------------------------------------------------------------------
// Fallback page for navigation when offline (optional)
// ------------------------------------------------------------------
self.addEventListener('fetch', (event) => {
  if (event.request.mode === 'navigate') {
    event.respondWith(
      fetch(event.request).catch(() => caches.match('offline.html'))
    );
  }
});

// Optional: listen for ‘skipWaiting’ message to activate new SW immediately
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});
